@'
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';
const summary=JSON.parse(fs.readFileSync('docs/benchmarks/2026-10-08-semantic-summary.json'));
let bytes=0;
for(const a of summary.attempts){bytes+=fs.statSync(a.file).size;const d=JSON.parse(gunzipSync(fs.readFileSync(a.file)));if(!d.completedAt||d.error)throw new Error(a.file);}
for(const f of ['README.md','docs/benchmarks/semantic-alternatives.md','docs/benchmarks/semantic-retrieval-pilot.md']){const text=fs.readFileSync(f,'utf8');console.log(JSON.stringify({file:f,emDashes:(text.match(/\u2014/g)||[]).length}));}
console.log(JSON.stringify({compressedEvidenceBytes:bytes,attempts:summary.attempts.length,protocolBeforeAllInference:summary.attempts.every(a=>JSON.parse(gunzipSync(fs.readFileSync(a.file))).startedAt>JSON.parse(fs.readFileSync('docs/benchmarks/2026-10-08-semantic-protocol.json')).createdAt)}));
'@ | node --input-type=module
& .dip-local/laya-env/Scripts/python.exe -m py_compile scripts/semantic-alternatives.py scripts/semantic-tensors.py
Remove-Item -LiteralPath scripts/__pycache__/semantic-alternatives.cpython-312.pyc, scripts/__pycache__/semantic-tensors.cpython-312.pyc
